    const session=new PythonSession({limits:{maxSteps:1000000,maxAllocatedBytes:16000000,maxDepth:1000},hashSeed:[1n,2n],output:{write(text){const bytes=Buffer.from(text);let offset=0;while(offset<bytes.length){const written=writeSync(fd,bytes,offset,bytes.length-offset,position);if(written<=0)throw Error('output made no progress');offset+=written;position+=written;writes++;}},flush(){fsyncSync(fd);flushes++;}}});
    const result=session.exec(row.source);
    fsyncSync(fd);flushes++;
    const stdout=readFileSync(outputPath,'utf8');reads++;
    rows.push({name:row.name,status:result.status,failure:result.status === 'terminated' ? result : undefined,stdout,matches:result.status==='ok'&&stdout===row.stdout});
  }
} finally{closeSync(fd);}
const report={reference:reference.reference,reads,writes,flushes,passed:rows.filter(r=>r.matches).length,failed:rows.filter(r=>!r.matches).length,cases:rows};
